package com.wayrapass.controller;import com.wayrapass.dto.request.CoordinatorRequest;import com.wayrapass.dto.response.UserResponse;import com.wayrapass.service.UserAdministrationService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/coordinators") @RequiredArgsConstructor @PreAuthorize("hasRole('COORDINATOR')") public class CoordinatorController{private final UserAdministrationService service;@PostMapping @ResponseStatus(HttpStatus.CREATED) public UserResponse create(@Valid @RequestBody CoordinatorRequest r){return service.createCoordinator(r);}}
